import csv,json,glob,hashlib,math,os
from pathlib import Path
import numpy as np
B=Path('[local path omitted]'); SB=Path('[local path omitted] 5/made/sb1-scale/diffimg'); TG=json.load(open(B.parent/'targets-selected.json'))
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
out=['# Independent batch 06 audit','', 'Audit uses measured quality-zero QLP SAP windows and historical difference images. Timing period errors are weighted linear-fit covariance with half-cadence floor and inflation at reduced chi-square > 1, conditional on chosen cycle counts and fitted shape; they are not total errors. Epoch is an ephemeris intercept near first observed eclipse, not necessarily a directly measured event. Primary designation is by convention unless parity establishes deeper event. Historical difference-image event centers were predicted and are not eclipse timings. Depth and fractional losses are blended aperture/pixel quantities, not neighbor intrinsic depths. Gaia G flux-ratio capability is an approximate screen, not a TESS passband or PRF measurement.', '']
for row in csv.DictReader(open(B/'queue.csv')):
 tic=row['tic']; m=json.load(open(B/tic/'measurements.json')); ds=list((SB/tic).glob('diff*.json')); g=json.load(open(SB/tic/'gaia.json')); gid=TG[tic]['gaia']['source_id']; assert str(g['src'][0]['source_id'])==str(gid); good=[e for e in m['events'] if e.get('timing_usable')]
 out+=['## TIC '+tic, f"Gaia identity {gid} verified against historical source. {len(good)} center candidates passing timing usability in sectors {','.join(map(str,sorted(set(e['sector'] for e in good))))}; fit uses {m.get('timing_event_count')} selected same-kind events; linear fit P={m.get('period_days')} ± {m.get('period_error_days')} d; intercept BTJD {m.get('primary_epoch_btjd')}; median blended depth {m.get('depth_ppt')} ppt; reduced chi-square {m.get('reduced_chi_square')}. First and last measured centers: {good[0]['mid_btjd']} and {good[-1]['mid_btjd']} BTJD. Epoch kind: {m.get('epoch_kind')}. "]
 for p in ds:
  d=json.load(open(p)); assert str(d['tic'])==tic;cap=[x for x in d['neighbours_60'] if x['possible']]; dist=math.dist(d['target_px'],d['deficit_centroid']);out += [f"Historical S{d['sector']} pixels: target {d['target_px']}, deficit centroid {d['deficit_centroid']} (offset {dist:.3f} pixel), aperture depths 1/3/5 = {d['depth_ap1']*1000:.2f}/{d['depth_ap3']*1000:.2f}/{d['depth_ap5']*1000:.2f} ppt; {len(cap)} G-screen capable neighbors within 60 arcsec."]
  if cap: out += ['Capable (Gaia ID, separation arcsec, G, estimated intrinsic loss if all flux admitted): '+ '; '.join(f"{x['source_id']} {x['sep']:.1f} {x['G']:.2f} {x['depth_needed']:.2f}" for x in cap)+'. Close sources and PSF overlap leave attribution conditional; pixel fractional loss is blended.']
  out += [f"Deciding historical diff: `{p}` SHA256 `{sha(p)}`; historical Gaia `{SB/tic/'gaia.json'}` SHA256 `{sha(SB/tic/'gaia.json')}`."]
 out += [f"Measured artifacts: `{B/tic/'measurements.json'}` SHA256 `{sha(B/tic/'measurements.json')}`; `{B/tic/'raw-windows.csv'}` SHA256 `{sha(B/tic/'raw-windows.csv')}`.", 'QLP FITS source identity and hash independently verified: '+ '; '.join(str(x['sector'])+' '+('OK' if sha(x['path'])==x['sha256'] else 'HASH MISMATCH')+' '+x['sha256'] for x in m['sources'])+'.', '']
 if tic in ('115106052','173040554'):
  out+=['Half-period fit mixes alternating conjunctions; same-parity independent fits follow:']
  for parity in (0,1):
   ev=[e for e in good if e['cycle']%2==parity]; n=np.array([(e['cycle']-parity)//2 for e in ev]); t=np.array([e['mid_btjd'] for e in ev]); er=np.array([e['timing_error_days'] for e in ev]);X=np.array([n*0+1,n-n.min()]).T;cov=np.linalg.inv((X/er[:,None]).T@(X/er[:,None])); b=cov@((X/er[:,None]).T@(t/er)); red=sum(((t-X@b)/er)**2)/max(len(n)-2,1);out += [f"Parity {parity}: {len(ev)} events, P={b[1]:.9f} ± {np.sqrt(cov[1,1]*max(red,1)):.9f} d, fitted epoch {b[0]:.6f} BTJD, first actual center {t[n.argmin()]:.6f}, median depth {np.median([e['depth_ppt'] for e in ev]):.2f} ppt, reduced chi-square {red:.2f}."]
  out+=['For TIC 115106052 parity 1 is deeper and alternating center deviations support the double period; for 173040554 depth ordering is suggestive but crowded and noisy, so provisional.','']
out+=['## Independent checks and limits', '396859601 S5 has four consecutive depressed points, two at eclipse core; its formal center covariance is zero and uninformative, and the half-cadence floor is conditional, not calibrated coverage. 20176241 S21 shows five depressed points and an egress gap. Both have two additional eclipses in later sectors. The earlier sparse dips support the long-baseline cycle assignment with these limitations. A center near the target is supportive but does not resolve a close capable neighbor. Aperture sizes are alternate reductions of the same photons, not independent observations. Geometry should be assessed against full Gaia SB1 covariance; linearized uncertainty and approximate stellar radii do not justify an arbitrary sigma veto.']
open(B/'helper-audit.md','w',encoding='utf8').write('\n'.join(out)+'\n')

p=B/'gaia-geometry.json'; geo=json.load(open(p)); out=['','## Gaia geometry numerical cross-check',f'Geometry artifact SHA256 `{sha(p)}`; full Gaia NSS SHA256 `{sha(B.parent/"shared-catalogues/gaia-nss-full.csv")}`. Conjunction phases approximate edge-on; uncertainty propagates Gaia covariance linearly and is not a total uncertainty or significance veto. Central durations assume TIC radii and minimum-mass companions, and may differ for noncentral eclipses.','','| TIC | Gaia P d | photometric minus Gaia P d | nearest conjunction phase offset | propagated Gaia d | observed / approximate central duration h |','|---|---:|---:|---:|---:|---:|']
for k,v in geo.items():out.append(f"| {k} | {v['period_days']:.8f} | {v['period_difference_days']:.8f} | {v['closest']['offset_phase']:.5f} | {v['closest']['gaia_covariance_linear_error_days']:.4f} | {v['observed_duration_hours']:.2f} / {v['central_duration_hours_approx']:.2f} |")
out+=['', 'I inspected raw-contact.png and diff-contact.png covering all ten. Fits show repeat dips; the 396 S5 depressed points are real-looking but sparse and excluded from precision timing. The 201 S21 repeat has a gap across egress; timing allowance is sensitivity analysis, not calibrated total uncertainty. Difference images support target-centered deficits, but close capable neighbors in 207813753, 173040554 and 67300566 remain materially unresolved; probable is an honest physical tier. For 144113939 and 387275908 the nearest capable neighbors are about 38.5 and 27.3 arcsec respectively and the deficit peaks near the target; confirmed is reasonable with remaining uncertainties stated. All five bounded checks can be completed even where attribution remains uncertain.']
with open(B/'helper-audit.md','a',encoding='utf8') as f:f.write('\n'.join(out)+'\n')
